/**
 * Miscellaneous Utility Converters
 *
 * Provides general-purpose conversion and utility functions used across
 * multiple SDK modules. These are intentionally co-located in the converters
 * module to avoid duplication.
 *
 * @module common/converters/miscellaneous
 * @since 2.0.0
 */

// =============================================================================
// TYPE UTILITIES
// =============================================================================

/**
 * Utility type that removes `readonly` modifiers from all properties of a type.
 *
 * This is useful when you need to create a mutable version of an immutable type,
 * such as when building objects incrementally before freezing them.
 *
 * @typeParam T - The type to make writable
 *
 * @remarks
 * The `-readonly` modifier removes the `readonly` attribute from each property,
 * effectively making all properties mutable.
 *
 * @example
 * ```typescript
 * interface ReadonlyUser {
 *     readonly id: string;
 *     readonly name: string;
 * }
 *
 * // MutableUser has { id: string; name: string } (no readonly)
 * type MutableUser = Writable<ReadonlyUser>;
 *
 * const user: MutableUser = { id: "1", name: "Alice" };
 * user.name = "Bob"; // OK - property is now writable
 * ```
 *
 * @since 2.0.0
 * @public
 */
export type Writable<T> = {
  -readonly [P in keyof T]: T[P];
};

// =============================================================================
// ASYNC UTILITIES
// =============================================================================

/**
 * Pauses execution for the specified number of milliseconds.
 *
 * @param ms - Duration to sleep in milliseconds. Must be a non-negative integer.
 * @returns A `Promise<void>` that resolves after `ms` milliseconds.
 *
 * @example
 * ```typescript
 * await sleep(2000); // Wait 2 seconds
 * ```
 *
 * @since 2.0.0
 * @public
 */
export async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// =============================================================================
// ENCODING UTILITIES
// =============================================================================

/**
 * Decodes a base64-encoded string into a `Uint8Array`.
 *
 * Works in both browser (using `atob`) and Node.js (using `Buffer`) environments,
 * selecting the appropriate decoding strategy at runtime.
 *
 * @param base64 - The base64-encoded string to decode.
 * @returns The decoded bytes as a `Uint8Array`.
 *
 * @throws {Error} If the input is not valid base64.
 *
 * @example
 * ```typescript
 * const bytes = base64ToUint8Array("SGVsbG8="); // Uint8Array([72, 101, 108, 108, 111])
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function base64ToUint8Array(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(base64, "base64"));
  }
  return Uint8Array.from(atob(base64), (c) => c.codePointAt(0) ?? 0);
}

/**
 * Encodes a `Uint8Array` into a base64 string.
 *
 * Works in both browser (using `btoa`) and Node.js (using `Buffer`) environments.
 *
 * @param bytes - The byte array to encode.
 * @returns The base64-encoded string.
 *
 * @example
 * ```typescript
 * const b64 = uint8ArrayToBase64(new Uint8Array([72, 101, 108, 108, 111])); // "SGVsbG8="
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function uint8ArrayToBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(bytes).toString("base64");
  }
  return btoa(String.fromCodePoint(...bytes));
}

// =============================================================================
// HEX ENCODING
// =============================================================================

/**
 * Decodes a hex string into a `Uint8Array`.
 *
 * @remarks
 * Accepts hex strings with or without a `0x` prefix. The input must have an
 * even number of hex characters (each byte is two hex digits).
 *
 * @param hex - The hex-encoded string to decode (e.g. `"48656c6c6f"` or `"0x48656c6c6f"`).
 * @returns The decoded bytes as a `Uint8Array`.
 *
 * @throws {Error} If the input contains non-hex characters or has odd length.
 *
 * @example
 * ```typescript
 * const bytes = hexToBytes("48656c6c6f"); // Uint8Array([72, 101, 108, 108, 111])
 * const bytes2 = hexToBytes("0x48656c6c6f"); // same result
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function hexToBytes(hex: string): Uint8Array {
  const cleaned = hex.startsWith("0x") || hex.startsWith("0X") ? hex.slice(2) : hex;
  if (cleaned.length % 2 !== 0) {
    throw new Error(`hexToBytes: hex string must have even length, got ${String(cleaned.length)}`);
  }
  const bytes = new Uint8Array(cleaned.length / 2);
  for (let i = 0; i < cleaned.length; i += 2) {
    const byte = parseInt(cleaned.substring(i, i + 2), 16);
    if (Number.isNaN(byte)) {
      throw new Error(`hexToBytes: invalid hex character at position ${String(i)}`);
    }
    bytes[i / 2] = byte;
  }
  return bytes;
}

/**
 * Encodes a `Uint8Array` into a lowercase hex string (without `0x` prefix).
 *
 * @param bytes - The byte array to encode.
 * @returns The hex-encoded string (lowercase, no prefix).
 *
 * @example
 * ```typescript
 * const hex = bytesToHex(new Uint8Array([72, 101, 108, 108, 111])); // "48656c6c6f"
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function bytesToHex(bytes: Uint8Array): string {
  let hex = "";
  for (const byte of bytes) {
    hex += byte.toString(16).padStart(2, "0");
  }
  return hex;
}

// =============================================================================
// GENERIC BIGINT ↔ BYTES
// =============================================================================

/**
 * Encodes a non-negative bigint into a little-endian byte array of the specified length.
 *
 * @param value - The non-negative bigint to encode.
 * @param byteLength - The number of output bytes. The value must fit within this many bytes.
 * @returns A `Uint8Array` of exactly `byteLength` bytes in little-endian order.
 *
 * @throws {RangeError} If `value` is negative or doesn't fit in `byteLength` bytes.
 *
 * @example
 * ```typescript
 * const bytes = encodeBigintToLeBytes(256n, 4); // Uint8Array([0, 1, 0, 0])
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function encodeBigintToLeBytes(value: bigint, byteLength: number): Uint8Array {
  if (value < 0n) {
    throw new RangeError(`encodeBigintToLeBytes: value must be non-negative, got ${String(value)}`);
  }
  const maxValue = (1n << BigInt(byteLength * 8)) - 1n;
  if (value > maxValue) {
    throw new RangeError(
      `encodeBigintToLeBytes: value ${String(value)} does not fit in ${String(byteLength)} bytes`,
    );
  }
  const bytes = new Uint8Array(byteLength);
  let remaining = value;
  for (let i = 0; i < byteLength; i++) {
    bytes[i] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return bytes;
}

/**
 * Encodes a non-negative bigint into a big-endian byte array of the specified length.
 *
 * @param value - The non-negative bigint to encode.
 * @param byteLength - The number of output bytes. The value must fit within this many bytes.
 * @returns A `Uint8Array` of exactly `byteLength` bytes in big-endian order.
 *
 * @throws {RangeError} If `value` is negative or doesn't fit in `byteLength` bytes.
 *
 * @example
 * ```typescript
 * const bytes = encodeBigintToBeBytes(256n, 4); // Uint8Array([0, 0, 1, 0])
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function encodeBigintToBeBytes(value: bigint, byteLength: number): Uint8Array {
  if (value < 0n) {
    throw new RangeError(`encodeBigintToBeBytes: value must be non-negative, got ${String(value)}`);
  }
  const maxValue = (1n << BigInt(byteLength * 8)) - 1n;
  if (value > maxValue) {
    throw new RangeError(
      `encodeBigintToBeBytes: value ${String(value)} does not fit in ${String(byteLength)} bytes`,
    );
  }
  const bytes = new Uint8Array(byteLength);
  let remaining = value;
  for (let i = byteLength - 1; i >= 0; i--) {
    bytes[i] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return bytes;
}

/**
 * Decodes a little-endian `Uint8Array` into a non-negative bigint.
 *
 * @param bytes - The little-endian byte array to decode.
 * @returns The decoded bigint value.
 *
 * @example
 * ```typescript
 * const value = decodeLeBytesToBigint(new Uint8Array([0, 1, 0, 0])); // 256n
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function decodeLeBytesToBigint(bytes: Uint8Array): bigint {
  let value = 0n;
  for (let i = bytes.length - 1; i >= 0; i--) {
    value = (value << 8n) | BigInt(bytes[i]);
  }
  return value;
}

/**
 * Decodes a big-endian `Uint8Array` into a non-negative bigint.
 *
 * @param bytes - The big-endian byte array to decode.
 * @returns The decoded bigint value.
 *
 * @example
 * ```typescript
 * const value = decodeBeBytesToBigint(new Uint8Array([0, 0, 1, 0])); // 256n
 * ```
 *
 * @since 2.0.0
 * @public
 */
export function decodeBeBytesToBigint(bytes: Uint8Array): bigint {
  let value = 0n;
  for (const byte of bytes) {
    value = (value << 8n) | BigInt(byte);
  }
  return value;
}
